1	package store
2	
3	import (
4		"context"
5		"database/sql"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"strings"
10	)
11	
12	// Resources is a workload request or a node capacity. CPU is in millicores and
13	// memory in MiB; both are non-negative 64-bit integers on the wire.
14	type Resources struct {
15		CPU    int64 `json:"cpu"`
16		Memory int64 `json:"memory"`
17	}
18	
19	// Node is one candidate node offered by a placement request.
20	type Node struct {
21		Name   string            `json:"name"`
22		CPU    int64             `json:"cpu"`
23		Memory int64             `json:"memory"`
24		Labels map[string]string `json:"labels"`
25	}
26	
27	// Placement is one stored scheduling decision: the request payload plus its
28	// status. Node and Reason are pointers so a rejected record renders them as
29	// JSON null.
30	type Placement struct {
31		Namespace string            `json:"namespace"`
32		Name      string            `json:"name"`
33		Queue     string            `json:"queue"`
34		Priority  int32             `json:"priority"`
35		Resources Resources         `json:"resources"`
36		Selector  map[string]string `json:"selector"`
37		Nodes     []Node            `json:"nodes"`
38		Status    string            `json:"status"`
39		Node      *string           `json:"node"`
40		Reason    *string           `json:"reason"`
41	}
42	
43	// ErrNotFound is returned by Get when no placement matches the identity.
44	var ErrNotFound = errors.New("placement not found")
45	
46	// Submit stores p the first time its (namespace, name) identity is seen. On a
47	// repeated submission it returns the previously stored record. created reports
48	// whether the row was inserted by this call.
49	func (s *Store) Submit(ctx context.Context, p *Placement) (stored *Placement, created bool, err error) {
50		payload, err := canonicalInput(p)
51		if err != nil {
52			return nil, false, fmt.Errorf("encode placement: %w", err)
53		}
54	
55		tx, err := s.db.BeginTx(ctx, nil)
56		if err != nil {
57			return nil, false, fmt.Errorf("begin submit: %w", err)
58		}
59		defer tx.Rollback()
60	
61		_, execErr := tx.ExecContext(ctx,
62			"INSERT INTO placements (namespace, name, input_json, status, node, reason) VALUES (?, ?, ?, ?, ?, ?)",
63			p.Namespace, p.Name, string(payload), p.Status, p.Node, p.Reason,
64		)
65		if execErr == nil {
66			if err := tx.Commit(); err != nil {
67				return nil, false, fmt.Errorf("commit submit: %w", err)
68			}
69			out := *p
70			return &out, true, nil
71		}
72		if !isUniqueViolation(execErr) {
73			return nil, false, fmt.Errorf("insert placement: %w", execErr)
74		}
75	
76		row := tx.QueryRowContext(ctx,
77			"SELECT input_json, status, node, reason FROM placements WHERE namespace = ? AND name = ?",
78			p.Namespace, p.Name,
79		)
80		var inputJSON, status string
81		var node, reason sql.NullString
82		if err := row.Scan(&inputJSON, &status, &node, &reason); err != nil {
83			return nil, false, fmt.Errorf("load existing placement: %w", err)
84		}
85		existing, err := decodeRecord(inputJSON, status, node, reason)
86		if err != nil {
87			return nil, false, err
88		}
89		return existing, false, nil
90	}
91	
92	// Get fetches a single placement by its identity. It returns ErrNotFound when
93	// the identity is unknown.
94	func (s *Store) Get(ctx context.Context, namespace, name string) (*Placement, error) {
95		row := s.db.QueryRowContext(ctx,
96			"SELECT input_json, status, node, reason FROM placements WHERE namespace = ? AND name = ?",
97			namespace, name,
98		)
99		var inputJSON, status string
100		var node, reason sql.NullString
101		if err := row.Scan(&inputJSON, &status, &node, &reason); err != nil {
102			if errors.Is(err, sql.ErrNoRows) {
103				return nil, ErrNotFound
104			}
105			return nil, fmt.Errorf("get placement: %w", err)
106		}
107		return decodeRecord(inputJSON, status, node, reason)
108	}
109	
110	// ListFilter narrows List; empty fields are ignored. Node never matches a
111	// rejected record.
112	type ListFilter struct {
113		Namespace string
114		Queue     string
115		Node      string
116	}
117	
118	// List returns committed placements matching f, sorted by namespace then name
119	// in UTF-8 byte order (SQLite BINARY text ordering).
120	func (s *Store) List(ctx context.Context, f ListFilter) ([]*Placement, error) {
121		var clauses []string
122		var args []any
123		if f.Namespace != "" {
124			clauses = append(clauses, "namespace = ?")
125			args = append(args, f.Namespace)
126		}
127		if f.Queue != "" {
128			clauses = append(clauses, "queue = ?")
129			args = append(args, f.Queue)
130		}
131		if f.Node != "" {
132			clauses = append(clauses, "node = ?")
133			args = append(args, f.Node)
134		}
135		query := "SELECT input_json, status, node, reason FROM placements"
136		if len(clauses) > 0 {
137			query += " WHERE " + strings.Join(clauses, " AND ")
138		}
139		query += " ORDER BY namespace, name"
140	
141		rows, err := s.db.QueryContext(ctx, query, args...)
142		if err != nil {
143			return nil, fmt.Errorf("list placements: %w", err)
144		}
145		defer rows.Close()
146	
147		var out []*Placement
148		for rows.Next() {
149			var inputJSON, status string
150			var node, reason sql.NullString
151			if err := rows.Scan(&inputJSON, &status, &node, &reason); err != nil {
152				return nil, fmt.Errorf("scan placement: %w", err)
153			}
154			rec, err := decodeRecord(inputJSON, status, node, reason)
155			if err != nil {
156				return nil, err
157			}
158			out = append(out, rec)
159		}
160		if err := rows.Err(); err != nil {
161			return nil, fmt.Errorf("iterate placements: %w", err)
162		}
163		return out, nil
164	}
165	
166	func decodeRecord(inputJSON, status string, node, reason sql.NullString) (*Placement, error) {
167		var in inputPayload
168		if err := json.Unmarshal([]byte(inputJSON), &in); err != nil {
169			return nil, fmt.Errorf("decode stored placement: %w", err)
170		}
171		p := &Placement{
172			Namespace: in.Namespace,
173			Name:      in.Name,
174			Queue:     in.Queue,
175			Priority:  in.Priority,
176			Resources: in.Resources,
177			Selector:  in.Selector,
178			Nodes:     in.Nodes,
179			Status:    status,
180		}
181		if node.Valid {
182			v := node.String
183			p.Node = &v
184		}
185		if reason.Valid {
186			v := reason.String
187			p.Reason = &v
188		}
189		return p, nil
190	}
191	
192	func isUniqueViolation(err error) bool {
193		msg := strings.ToLower(err.Error())
194		return strings.Contains(msg, "unique constraint failed")
195	}
