1	package service
2	
3	import (
4		"context"
5		"errors"
6		"net/url"
7		"path/filepath"
8		"testing"
9	
10		"github.com/Bob-xisuke/orb-scheduler-core/internal/store"
11	)
12	
13	// seedPlacement registers one placement through Accept so query tests work on
14	// committed data produced by the real write path.
15	func seedPlacement(t *testing.T, svc *Service, namespace, name, queue string, nodes []store.Node) *store.Placement {
16		t.Helper()
17		p := &store.Placement{
18			Namespace: namespace,
19			Name:      name,
20			Queue:     queue,
21			Priority:  1,
22			Resources: store.Resources{CPU: 100, Memory: 64},
23			Selector:  map[string]string{},
24			Nodes:     nodes,
25		}
26		rec, outcome, err := svc.Accept(context.Background(), p)
27		if err != nil {
28			t.Fatalf("seed %s/%s: %v", namespace, name, err)
29		}
30		if outcome != Created {
31			t.Fatalf("seed %s/%s: outcome = %d, want Created", namespace, name, outcome)
32		}
33		return rec
34	}
35	
36	func eligibleNode(name string) []store.Node {
37		return []store.Node{{Name: name, CPU: 1000, Memory: 512, Labels: map[string]string{}}}
38	}
39	
40	func TestQuerySingleRecordReturnsAllFields(t *testing.T) {
41		_, svc := newService(t)
42		seeded := seedPlacement(t, svc, "team-a", "job-1", "default", eligibleNode("node-a"))
43	
44		result, err := svc.Query(context.Background(), url.Values{
45			"namespace": {"team-a"},
46			"name":      {"job-1"},
47		})
48		if err != nil {
49			t.Fatalf("query: %v", err)
50		}
51		if result.Record == nil || result.Items != nil {
52			t.Fatalf("single success must set only Record: %+v", result)
53		}
54		rec := result.Record
55		if rec.Namespace != seeded.Namespace || rec.Name != seeded.Name || rec.Queue != seeded.Queue ||
56			rec.Priority != seeded.Priority || rec.Resources != seeded.Resources ||
57			rec.Status != StatusPlaced || rec.Node == nil || *rec.Node != "node-a" || rec.Reason != nil {
58			t.Fatalf("record fields not preserved: %+v", rec)
59		}
60		if len(rec.Nodes) != 1 || rec.Nodes[0].Name != "node-a" || rec.Selector == nil {
61			t.Fatalf("request half not preserved: %+v", rec)
62		}
63	}
64	
65	func TestQuerySingleRejectedRecordKeepsNullNodeAndReason(t *testing.T) {
66		_, svc := newService(t)
67		// No eligible node: the stored record is a rejection.
68		seedPlacement(t, svc, "team-a", "job-2", "default", []store.Node{})
69	
70		result, err := svc.Query(context.Background(), url.Values{
71			"namespace": {"team-a"},
72			"name":      {"job-2"},
73		})
74		if err != nil {
75			t.Fatalf("query: %v", err)
76		}
77		rec := result.Record
78		if rec == nil || rec.Status != StatusRejected || rec.Node != nil || rec.Reason == nil || *rec.Reason != ReasonNoNode {
79			t.Fatalf("rejected record mismatch: %+v", rec)
80		}
81	}
82	
83	func TestQuerySingleMissingIdentity(t *testing.T) {
84		_, svc := newService(t)
85		result, err := svc.Query(context.Background(), url.Values{
86			"namespace": {"team-a"},
87			"name":      {"missing"},
88		})
89		if !errors.Is(err, ErrPlacementNotFound) {
90			t.Fatalf("err = %v, want ErrPlacementNotFound", err)
91		}
92		if result.Record != nil || result.Items != nil {
93			t.Fatalf("failure must leave both fields nil: %+v", result)
94		}
95	}
96	
97	func TestQueryInvalidParameterSets(t *testing.T) {
98		_, svc := newService(t)
99		cases := map[string]url.Values{
100			"unknown key":          {"bogus": {"x"}},
101			"known plus unknown":   {"namespace": {"a"}, "bogus": {"x"}},
102			"repeated value":       {"namespace": {"a", "b"}},
103			"empty value":          {"namespace": {""}},
104			"name without ns":      {"name": {"job"}},
105			"name with queue":      {"namespace": {"a"}, "name": {"job"}, "queue": {"q"}},
106			"name with node":       {"namespace": {"a"}, "name": {"job"}, "node": {"n"}},
107			"name with everything": {"namespace": {"a"}, "name": {"job"}, "queue": {"q"}, "node": {"n"}},
108		}
109		for label, values := range cases {
110			result, err := svc.Query(context.Background(), values)
111			if !errors.Is(err, ErrInvalidPlacementQuery) {
112				t.Errorf("%s: err = %v, want ErrInvalidPlacementQuery", label, err)
113			}
114			if result.Record != nil || result.Items != nil {
115				t.Errorf("%s: failure must leave both fields nil: %+v", label, result)
116			}
117		}
118	}
119	
120	func TestQueryValidationFailureDoesNotTouchStorage(t *testing.T) {
121		st, svc := newService(t)
122		if err := st.Close(); err != nil {
123			t.Fatalf("close: %v", err)
124		}
125		// With the store closed, any storage access would surface as
126		// ErrStorageUnavailable; an invalid query must still report the
127		// validation error.
